[ExtensionOf(classStr(PurchConfirmationJournalCreate))]
final class METPurchConfirmationJournalCreate_Extension
{
    private METTotalNetVolume totalVolume = 0;
    private METTotalNetWeight totalWeight = 0;
}

Method.Source:
    protected void createJournalLine(Common _purchLine)
    {
        PurchLine               purchLine = _purchLine as PurchLine;
        METPurchLine            metPurchLine;
        PurchLineAllVersions    purchLineAllVersions;

        next createJournalLine(_purchLine);

        select count(RecId) from purchLineAllVersions
            where   purchLineAllVersions.PurchId        == purchLine.PurchId &&
                    purchLineAllVersions.InventTransId  == purchLine.InventTransId &&
                    purchLineAllVersions.IsArchived     == NoYes::No;

        if(purchLineAllVersions.RecId == 1)
        {
            metPurchLine = purchLine.metPurchLine();

            if(metPurchLine)
            { 
                metPurchLine.selectForUpdate(true);

                metPurchLine.WeightPerQty = METWHSPhysDimUOMSite::convertWeight(purchLine.ItemId, 1, purchLine.PurchUnit, purchLine.inventDim());
                metPurchLine.VolumePerQty = METWHSPhysDimUOMSite::convertVolume(purchLine.ItemId, 1, purchLine.PurchUnit, purchLine.inventDim());

                totalVolume += purchline.PurchQty * metPurchLine.VolumePerQty;
                totalWeight += purchline.PurchQty * metPurchLine.WeightPerQty;

                metPurchLine.update();
            }
        }
    }

    protected void endCreate()
    {
        VendPurchOrderJour  localVendPurchOrderJour = this.getJournal() as VendPurchOrderJour;

        localVendPurchOrderJour.selectForUpdate(true);

        localVendPurchOrderJour.Volume = totalVolume;
        localVendPurchOrderJour.Weight = totalWeight;

        localVendPurchOrderJour.update();

        next endCreate();
    }
